<template>
  <div class="app-container">
    <div class="page-hero"><div class="hero-inner"><div class="hero-text"><h1 class="hero-title">变量聚类分析</h1><p class="hero-desc">R 型（变量）层次聚类，使用 Pearson 相关系数作为相似度度量（距离 = 1-|r|），最远邻法合并，输出相关系数矩阵和聚类过程表</p></div><el-tag class="hero-tag" effect="dark" round>CLUSTER · R-TYPE</el-tag></div></div>
    <el-row :gutter="20" class="mb-4 input-row">
      <el-col :lg="16" :xs="24"><el-card shadow="never" class="input-card"><el-form label-position="top"><el-form-item label="数据（每行一条观测，列为变量）"><el-input v-model="form.rawData" type="textarea" :rows="6" /></el-form-item></el-form><div class="action-bar"><el-button type="primary" class="calc-btn" @click="calculate"><el-icon class="mr-1"><DataAnalysis /></el-icon>开始计算</el-button><el-button class="reset-btn" @click="loadDemo">加载示例</el-button><el-button class="reset-btn" @click="clearAll">清除</el-button></div></el-card></el-col>
      <el-col :lg="8" :xs="24"><div class="param-sidebar"><div class="param-sidebar-header"><el-icon class="sidebar-icon"><InfoFilled /></el-icon>检验原理</div><div class="principle-content"><div class="principle-block"><div class="principle-label">相似度</div><p>Pearson 相关系数 r</p><div class="formula-box">距离 = 1 - |r|</div></div><div class="principle-block"><div class="principle-label">合并规则</div><p>最远邻法（Complete Linkage）</p></div></div><div class="ref-section"><div class="ref-title">参考文献</div><p class="ref-item">[1] 方积乾.《卫生统计学》第7版, 2012.</p></div></div></el-col>
    </el-row>
    <transition name="result-fade"><div v-if="res" class="result-section">
      <el-row :gutter="20" class="mb-4">
        <el-col :lg="12" :xs="24" class="mb-4"><el-card shadow="never" class="detail-card"><template #header><div class="card-header-inner"><el-icon class="header-icon"><Document /></el-icon><span class="font-bold">相关系数矩阵</span></div></template><el-table :data="corTable" size="small" stripe border><el-table-column v-for="(_, j) in corTable[0]" :key="j" :prop="'c' + j" :label="j === 0 ? '' : 'V' + j" width="80" /></el-table></el-card></el-col>
        <el-col :lg="12" :xs="24" class="mb-4"><el-card shadow="never" class="detail-card"><template #header><div class="card-header-inner"><el-icon class="header-icon"><Document /></el-icon><span class="font-bold">聚类过程</span></div></template><el-table :data="mergeSteps" size="small" stripe border><el-table-column prop="step" label="步骤" width="60" /><el-table-column prop="c1" label="合并类1" /><el-table-column prop="c2" label="合并类2" /><el-table-column prop="corr" label="相关系数" /></el-table></el-card></el-col>
      </el-row>
    </div></transition>
  </div>
</template>
<script setup lang="ts">
import { InfoFilled, DataAnalysis, Document } from "@element-plus/icons-vue"; import * as S from "../utils/stats";
defineOptions({ name: "ClusterVariable" }); const form = reactive({ rawData: "" }); const res = ref(false); const corTable = ref<any[]>([]); const mergeSteps = ref<any[]>([]);
function loadDemo() { form.rawData = "40.03,88.57,72.3\n97.13,88.00,95.1\n80.32,123.72,102.5\n25.32,39.03,30.2\n19.61,24.37,22.0\n14.50,192.75,100.3\n49.63,121.57,85.4\n44.56,89.76,67.1"; calculate(); }
function clearAll() { form.rawData = ""; res.value = false; }
function calculate() {
  const matrix = form.rawData.trim().split("\n").map(l => S.parseNumbers(l)); const n = matrix.length, p = matrix[0]?.length || 0; if (n < 3 || p < 2) return;
  const cols: number[][] = Array.from({ length: p }, (_, j) => matrix.map(row => row[j]));
  const cor: number[][] = Array.from({ length: p }, (_, i) => Array.from({ length: p }, (_, j) => i === j ? 1 : S.pearsonR(cols[i], cols[j])));
  corTable.value = cor.map((row, i) => { const obj: any = { c0: `V${i + 1}` }; row.forEach((v, j) => obj['c' + (j + 1)] = S.fmt(v, 3)); return obj; });
  const dist: number[][] = cor.map(row => row.map(r => 1 - Math.abs(r)));
  const clusters: number[][] = cols.map((_, i) => [i]); const steps: any[] = [];
  for (let step = 1; step < p; step++) { let minDist = Infinity, mi = -1, mj = -1; for (let i = 0; i < clusters.length; i++) for (let j = i + 1; j < clusters.length; j++) { let maxD = 0; for (const a of clusters[i]) for (const b of clusters[j]) maxD = Math.max(maxD, dist[a][b]); if (maxD < minDist) { minDist = maxD; mi = i; mj = j; } } if (mi < 0) break; steps.push({ step, c1: clusters[mi].map(x => `V${x + 1}`).join(","), c2: clusters[mj].map(x => `V${x + 1}`).join(","), corr: S.fmt(1 - minDist, 3) }); clusters[mi] = [...clusters[mi], ...clusters[mj]]; clusters.splice(mj, 1); }
  mergeSteps.value = steps; res.value = true;
}
</script>
