olid var(--el-color-primary)}.principle-block p{margin:3px 0}.formula-box{font-family:"JetBrains Mono",monospace;font-size:12px;padding:8px 12px;border-radius:8px;background:rgba(var(--el-color-primary-rgb,64,158,255),.05);margin:6px 0;font-weight:600}.ref-section{margin-top:16px;padding-top:12px;border-top:1px dashed var(--el-border-color-lighter)}.ref-title{font-size:12px;font-weight:700;margin-bottom:8px;padding-left:8px;border-left:3px solid var(--el-color-warning)}.ref-item{font-size:11px;line-height:1.6;color:var(--el-text-color-secondary);margin:2px 0}.result-fade-enter-active{transition:all .5s cubic-bezier(.16,1,.3,1)}.result-fade-leave-active{transition:all .3s ease}.result-fade-enter-from{opacity:0;transform:translateY(24px)}.result-fade-leave-to{opacity:0;transform:translateY(-12px)}.result-section{animation:slideUp .5s cubic-bezier(.16,1,.3,1)}@keyframes slideUp{from{opacity:0;transform:translateY(20px)}to{opacity:1;transform:translateY(0)}}.card-header-inner{display:flex;align-items:center;gap:8px}.header-icon{font-size:16px;color:var(--el-color-primary)}.detail-card{border-radius:14px}</style>
